"""Customer-readable task artifacts generated from the machine task plan."""
from __future__ import annotations

from collections import Counter
from html import escape


def render_technical_tasks_markdown(plan: dict) -> str:
    lines = [
        "# Operational Dashboard Technical Delivery Plan", "",
        f"- Status: `{plan['status']}`", f"- Feature: `{plan['feature_id']}`",
        f"- Architecture: `LOCKED`", f"- Design: `{plan['design']['status']}` / `{plan['design']['mode']}`", "",
        "## Delivery Sequence", "",
    ]
    for task in plan["tasks"]:
        dependencies = ", ".join(task["dependencies"]) or "None"
        lines.extend([f"### {task['task_id']} · {task['title']}", "", f"**Category:** `{task['category']}`", f"**Depends on:** {dependencies}", "", task["objective"], "", "**Implementation requirements**", *[f"- {item}" for item in task["implementation_requirements"]], "", "**Validation**", *[f"- {item}" for item in task["validation_requirements"]], "", f"**Architecture:** {', '.join(task['architecture_decision_refs'])}", f"**Requirements:** {', '.join(task['functional_requirement_refs']) or 'Infrastructure task'}", f"**APIs:** {', '.join(task['api_refs']) or 'None'}", f"**Design:** {', '.join(task['design_refs']) or plan['design']['status']}", ""])
    return "\n".join(lines)


def render_technical_tasks_html(plan: dict) -> str:
    tasks = plan["tasks"]
    counts = Counter(item["category"] for item in tasks)
    task_cards = "".join(_task_card(item, plan["design"]["status"]) for item in tasks)
    roadmap = "".join(f'<li><b>{escape(item["task_id"])}</b><span>{escape(item["title"])}</span><small>After {escape(", ".join(item["dependencies"]) or "foundation")}</small></li>' for item in tasks)
    category_cards = "".join(f"<article><strong>{count}</strong><span>{escape(category)}</span></article>" for category, count in sorted(counts.items()))
    api_cards = "".join(f'<article><span>{escape(api["method"])}</span><code>{escape(api["endpoint"])}</code><p>{escape(api["response_description"])}</p></article>' for api in plan["existing_api_contracts"])
    integration = "".join(_task_card(item, plan["design"]["status"]) for item in tasks if item["category"] in {"GATEWAY", "BFF", "INTEGRATION", "SECURITY_CONTEXT", "OBSERVABILITY"})
    architecture_ids = list(dict.fromkeys(ref for item in tasks for ref in item["architecture_decision_refs"]))
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Operational Dashboard Technical Delivery Plan</title><style>
:root{{--ink:#102e35;--deep:#123d46;--teal:#08776e;--aqua:#bce5d9;--cream:#f4eddf;--paper:#fffdf8;--orange:#df6538;--line:#c9d7d2;--muted:#577075}}*{{box-sizing:border-box}}html{{scroll-behavior:smooth}}body{{margin:0;background:var(--cream);color:var(--ink);font:16px/1.55 "Trebuchet MS",sans-serif}}body:before{{content:"";position:fixed;inset:0;pointer-events:none;opacity:.2;background:radial-gradient(#08776e .7px,transparent .7px);background-size:19px 19px}}h1,h2,h3{{font-family:Georgia,serif;line-height:1.08}}h1{{font-size:clamp(3.5rem,8vw,7rem);max-width:1000px;margin:.15em 0}}h2{{font-size:clamp(2.1rem,4vw,3.4rem)}}code{{font-family:Consolas,monospace}}.wrap{{width:min(1180px,92vw);margin:auto}}header{{min-height:90vh;display:grid;align-items:center;color:white;background:linear-gradient(125deg,#0e3239,#12545a 66%,#0a786d);position:relative;overflow:hidden}}header:after{{content:"PLAN";position:absolute;right:-2rem;bottom:-3rem;font:700 14vw Georgia;color:#ffffff0b}}.kicker{{color:#9ae1d2;letter-spacing:.18em;font-weight:bold}}.lede{{font:1.35rem/1.5 Georgia;max-width:760px;color:#deeee9}}.pills,.refs{{display:flex;flex-wrap:wrap;gap:.55rem}}.pills span,.refs span{{border:1px solid #ffffff55;padding:.4rem .65rem}}section{{padding:5rem 0;position:relative}}section.alt{{background:var(--paper)}}.summary,.categories,.api-grid,.task-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}}.summary article,.categories article,.api-grid article{{background:white;padding:1.3rem;border-top:4px solid var(--orange)}}.summary strong,.categories strong{{display:block;font:2.2rem Georgia}}.categories span{{font-size:.75rem;font-weight:bold;letter-spacing:.1em}}.roadmap{{list-style:none;padding:0;display:grid;grid-template-columns:repeat(4,1fr);gap:1rem;counter-reset:item}}.roadmap li{{background:var(--deep);color:white;padding:1.2rem;min-height:150px;border-bottom:5px solid var(--aqua)}}.roadmap b,.roadmap span,.roadmap small{{display:block}}.roadmap b{{color:#9ae1d2}}.roadmap small{{margin-top:.8rem;color:#c4d9d7}}.task{{background:white;padding:1.5rem;border-left:5px solid var(--teal);box-shadow:0 10px 30px #10343c18}}.task-head{{display:flex;justify-content:space-between;gap:1rem}}.badge{{font-size:.68rem;font-weight:bold;letter-spacing:.08em;background:var(--aqua);padding:.35rem .55rem;height:max-content}}.meta{{display:grid;grid-template-columns:1fr 1fr;gap:.8rem;border-top:1px solid var(--line);padding-top:1rem}}.meta dt{{font-size:.68rem;font-weight:bold;color:var(--muted);letter-spacing:.08em}}.meta dd{{margin:0 0 .5rem;overflow-wrap:anywhere}}details summary{{cursor:pointer;font-weight:bold}}.integration{{background:var(--deep);color:white}}.integration .task{{color:var(--ink)}}.api-grid span{{background:var(--orange);color:white;font-weight:bold;padding:.25rem .5rem;margin-right:.5rem}}.priority{{display:grid;grid-template-columns:repeat(4,1fr);gap:.4rem;align-items:center}}.priority div{{padding:1.2rem;text-align:center;background:white;border-bottom:4px solid var(--teal)}}footer{{background:#092a31;color:#d4e7e3;padding:3rem 0}}@media(max-width:850px){{.summary,.categories,.api-grid,.task-grid,.roadmap,.priority{{grid-template-columns:1fr}}.meta{{grid-template-columns:1fr}}}}</style></head><body>
<header><div class="wrap"><p class="kicker">LOCKED ARCHITECTURE · DELIVERY-READY PLAN</p><h1>Operational Dashboard</h1><p class="lede">A sequenced Angular 22 delivery plan for one representative hero Feature, preserving approved requirements and all existing backend contracts.</p><div class="pills"><span>{len(tasks)} TECHNICAL TASKS</span><span>{len(counts)} DELIVERY AREAS</span><span>DESIGN {escape(plan['design']['mode'])}</span><span>{escape(plan['status'])}</span></div></div></header>
<main><section><div class="wrap"><h2>Delivery Summary</h2><div class="summary"><article><strong>{len(tasks)}</strong>ordered tasks</article><article><strong>{len(plan['existing_api_contracts'])}</strong>preserved APIs</article><article><strong>{len(plan['acceptance_criteria'])}</strong>hero acceptance criteria</article></div><h3>Selected architecture consumed</h3><div class="refs">{''.join(f'<span>{escape(ref)}</span>' for ref in architecture_ids)}</div></div></section>
<section class="alt"><div class="wrap"><h2>Implementation Roadmap</h2><ol class="roadmap">{roadmap}</ol></div></section>
<section><div class="wrap"><h2>Angular / Nx Delivery Areas</h2><div class="categories">{category_cards}</div><h2>Technical Tasks</h2><div class="task-grid">{task_cards}</div></div></section>
<section class="integration"><div class="wrap"><h2>Gateway / BFF Delivery Areas</h2><p>Target work only. Future facade contracts remain <code>TARGET_CONTRACT_TO_BE_DESIGNED</code>; existing backend semantics remain unchanged.</p><div class="task-grid">{integration}</div></div></section>
<section class="alt"><div class="wrap"><h2>Existing API Contracts</h2><p>These are the only existing Dashboard APIs represented by the plan.</p><div class="api-grid">{api_cards}</div></div></section>
<section><div class="wrap"><h2>Design Input Status</h2><div class="summary"><article><strong>{escape(plan['design']['provider'])}</strong>provider</article><article><strong>{escape(plan['design']['mode'])}</strong>mode</article><article><strong>{escape(plan['design']['status'])}</strong>status</article></div><p>Design controls presentation. Approved requirements control functionality. Locked architecture controls technical structure.</p></div></section>
<section class="alt"><div class="wrap"><h2>Testing & Traceability</h2><div class="priority"><div>Feature</div><div>Requirements & Stories</div><div>Architecture & APIs</div><div>Tasks & Future Tests</div></div><p>Unit, component, accessibility, integration, and Playwright tasks preserve authoritative acceptance-criteria references.</p></div></section></main>
<footer><div class="wrap"><h2>{escape(plan['status'])}</h2><p>Ready for Angular hero Feature generation. No application, Gateway, or BFF implementation is included in this stage.</p></div></footer></body></html>'''


def _task_card(task: dict, design_status: str) -> str:
    def refs(values: list[str], fallback: str = "None") -> str:
        return escape(", ".join(values) or fallback)
    requirements = "".join(f"<li>{escape(item)}</li>" for item in task["implementation_requirements"])
    validation = "".join(f"<li>{escape(item)}</li>" for item in task["validation_requirements"])
    return f'''<article class="task"><div class="task-head"><div><small>{escape(task['task_id'])} · ORDER {task['implementation_order']}</small><h3>{escape(task['title'])}</h3></div><span class="badge">{escape(task['category'])}</span></div><p>{escape(task['objective'])}</p><details><summary>Implementation and validation</summary><h4>Requirements</h4><ul>{requirements}</ul><h4>Validation</h4><ul>{validation}</ul></details><dl class="meta"><div><dt>DEPENDENCIES</dt><dd>{refs(task['dependencies'], 'Foundation')}</dd><dt>ARCHITECTURE</dt><dd>{refs(task['architecture_decision_refs'])}</dd><dt>REQUIREMENTS</dt><dd>{refs(task['functional_requirement_refs'], 'Infrastructure')}</dd></div><div><dt>APIs</dt><dd>{refs(task['api_refs'])}</dd><dt>DESIGN</dt><dd>{refs(task['design_refs'], design_status)}</dd><dt>AC</dt><dd>{refs(task['acceptance_criteria_refs'])}</dd></div></dl></article>'''
